// CryPhoneTracker - entity component driving an entity transform from the phone 6DoF tracker.#pragma once#include <CryEntitySystem/IEntitySystem.h>#include <CryEntitySystem/IEntityComponent.h>#include <CryNetwork/CrySocks.h>#include <vector>#include <CrySchematyc/MathTypes.h>#include <CrySchematyc/ResourceTypes.h>#include <CrySchematyc/Env/IEnvRegistrar.h>#include <CrySchematyc/Utils/SharedString.h>#include "PhoneTrackerProtocol.h"#include "PoseFilter.h"#include "../../CinematicCamera/Interface/ICinematicCameraOptics.h"namespace Cry{namespace PhoneTracker{//! Reflection for the pose filter master switch, so it shows up as a combo box in the panel.static void ReflectType(Schematyc::CTypeDesc<EPoseFilterMode>& desc){	desc.SetGUID("{9E4F2B07-5D31-4A6C-8B72-1C0D5A93E4F6}"_cry_guid);	desc.SetLabel("Filter Mode");	desc.SetDefaultValue(EPoseFilterMode::Cinematic);	desc.AddConstant(EPoseFilterMode::Off,       "Off",       "Off");	desc.AddConstant(EPoseFilterMode::OneEuro,   "OneEuro",   "One Euro");	desc.AddConstant(EPoseFilterMode::Cinematic, "Cinematic", "Cinematic");}//! Binds an entity to the Android ARCore tracker: listens for pose packets on a UDP port and//! writes the received 6DoF pose into the entity transform every frame.struct SPhoneConnectionParams{	inline bool operator==(const SPhoneConnectionParams& rhs) const { return 0 == memcmp(this, &rhs, sizeof(rhs)); }	static void ReflectType(Schematyc::CTypeDesc<SPhoneConnectionParams>& desc)	{		desc.SetGUID("{93F6E82C-B5DA-449F-92E7-6A83FC4935F9}"_cry_guid);		desc.SetLabel("Connection");		desc.AddMember(&SPhoneConnectionParams::enabled, 'enab', "Enabled", "Enabled", "Open the socket and drive the entity while in game/simulation mode", true);		desc.AddMember(&SPhoneConnectionParams::port, 'port', "Port", "Listen Port", "UDP port the phone sends pose packets to", 9050);		desc.AddMember(&SPhoneConnectionParams::trackerId, 'tid', "TrackerId", "Tracker ID", "Number shown in logs and the debug overlay so multiple trackers can be told apart. 0 = automatic (order of creation)", 0);	}	bool enabled = true;	Schematyc::Range<1, 65535, 1024, 65535, int> port = 9050;	Schematyc::Range<0, 99, 0, 99, int> trackerId = 0;};struct SPhoneMappingParams{	inline bool operator==(const SPhoneMappingParams& rhs) const { return 0 == memcmp(this, &rhs, sizeof(rhs)); }	static void ReflectType(Schematyc::CTypeDesc<SPhoneMappingParams>& desc)	{		desc.SetGUID("{A407F93D-C6EB-45A0-93F8-7B94FD5A460A}"_cry_guid);		desc.SetLabel("Transform Mapping");		desc.AddMember(&SPhoneMappingParams::followActiveCamera, 'folw', "FollowActiveCamera", "Follow Active Camera", "Drive whichever Cinematic Camera is currently active (switch with 'ccam_slot N') instead of this entity. On every switch the tracker re-anchors at the new camera's position, so the phone carries on from wherever that camera was placed. Falls back to this entity when no cinematic camera is active", true);		desc.AddMember(&SPhoneMappingParams::applyPosition, 'apos', "ApplyPosition", "Apply Position", "Write the tracked translation into the entity transform", true);		desc.AddMember(&SPhoneMappingParams::applyRotation, 'arot', "ApplyRotation", "Apply Rotation", "Write the tracked rotation into the entity transform", true);		desc.AddMember(&SPhoneMappingParams::relativeToStartTransform, 'rel', "Relative", "Relative To Start", "Treat the tracker origin as the entity transform captured when tracking started. Disable to place the entity at raw tracker coordinates", true);		desc.AddMember(&SPhoneMappingParams::alignYawOnStart, 'ayaw', "AlignYawOnStart", "Align Yaw On Start", "Anchor using only the yaw of the starting poses (phone and entity). Pitch and roll stay gravity aligned, so turning the phone always rotates the entity around the world up axis - without this, a tilted phone at capture time tilts the whole rotation frame", true);		desc.AddMember(&SPhoneMappingParams::scale, 'scal', "Scale", "Metres To Units", "Multiplier applied to the tracked translation (1 = 1 metre per engine unit)", 1.0f);		desc.AddMember(&SPhoneMappingParams::yawOffsetDegrees, 'yaw', "YawOffset", "Yaw Offset", "Rotation around Z applied to the tracked motion, to align the phone heading with the scene", 0.0f);		desc.AddMember(&SPhoneMappingParams::positionOffset, 'poff', "PositionOffset", "Position Offset", "Extra world space offset added after the tracked translation", Vec3(ZERO));	}	bool followActiveCamera = true;	bool applyPosition = true;	bool applyRotation = true;	bool relativeToStartTransform = true;	bool alignYawOnStart = true;	Schematyc::Range<0, 1000, 0, 10> scale = 1.0f;	Schematyc::Range<-360, 360> yawOffsetDegrees = 0.0f;	Vec3 positionOffset = ZERO;};struct SPhoneFilterParams{	inline bool operator==(const SPhoneFilterParams& rhs) const { return 0 == memcmp(this, &rhs, sizeof(rhs)); }	static void ReflectType(Schematyc::CTypeDesc<SPhoneFilterParams>& desc)	{		desc.SetGUID("{B518FA4E-D7FC-46B1-84F9-8CA5FE6B571B}"_cry_guid);		desc.SetLabel("Pose Filter");		desc.AddMember(&SPhoneFilterParams::filterMode, 'fmod', "FilterMode", "Filter Mode", "Off reproduces the unfiltered behaviour exactly. One Euro adds clock rebasing, adaptive smoothing and fixed delay resampling. Cinematic adds the virtual tripod on top", EPoseFilterMode::Cinematic);		desc.AddMember(&SPhoneFilterParams::posMinCutoff, 'pmcu', "PosMinCutoff", "Position Min Cutoff", "Hz. Lower values kill more jitter while the camera is still", 1.0f);		desc.AddMember(&SPhoneFilterParams::posBeta, 'pbet', "PosBeta", "Position Speed Coefficient", "How fast the position cutoff opens up with speed, per m/s. Raise it if fast moves feel laggy", 0.5f);		desc.AddMember(&SPhoneFilterParams::rotMinCutoff, 'rmcu', "RotMinCutoff", "Rotation Min Cutoff", "Hz. Lower values kill more rotational jitter while the camera is still", 1.2f);		desc.AddMember(&SPhoneFilterParams::rotBeta, 'rbet', "RotBeta", "Rotation Speed Coefficient", "How fast the rotation cutoff opens up with angular rate, per rad/s", 0.1f);		desc.AddMember(&SPhoneFilterParams::interpDelayFactor, 'idly', "InterpDelay", "Resample Delay", "Packet intervals of buffering used to hide network jitter. Higher is smoother but adds latency", 1.5f);		desc.AddMember(&SPhoneFilterParams::maxExtrapolationMs, 'xtrp', "MaxExtrapolation", "Max Extrapolation", "Milliseconds the pose may be extrapolated into a signal gap. 0 freezes on the last pose instead", 0.0f);	}	EPoseFilterMode filterMode = EPoseFilterMode::Cinematic;	Schematyc::Range<0, 10, 0, 5> posMinCutoff = 1.0f;	Schematyc::Range<0, 5, 0, 2> posBeta = 0.5f;	Schematyc::Range<0, 10, 0, 5> rotMinCutoff = 1.2f;	Schematyc::Range<0, 5, 0, 2> rotBeta = 0.1f;	Schematyc::Range<1, 4, 1, 4> interpDelayFactor = 1.5f;	Schematyc::Range<0, 80, 0, 80> maxExtrapolationMs = 0.0f;};struct SPhoneTripodParams{	inline bool operator==(const SPhoneTripodParams& rhs) const { return 0 == memcmp(this, &rhs, sizeof(rhs)); }	static void ReflectType(Schematyc::CTypeDesc<SPhoneTripodParams>& desc)	{		desc.SetGUID("{C629FB5F-E80D-47C2-85FA-9DB6FF7C682C}"_cry_guid);		desc.SetLabel("Virtual Tripod");		desc.AddMember(&SPhoneTripodParams::tripodEnabled, 'trip', "Tripod", "Virtual Tripod", "Lock the pose completely once the operator holds still, so composing a shot is rock steady", true);		desc.AddMember(&SPhoneTripodParams::tripodEnterSpeed, 'tesp', "TripodEnterSpeed", "Tripod Enter Speed", "Metres per second below which the tripod starts arming", 0.015f);		desc.AddMember(&SPhoneTripodParams::tripodHoldTime, 'thld', "TripodHoldTime", "Tripod Hold Time", "Seconds of stillness required before the pose locks", 0.25f);		desc.AddMember(&SPhoneTripodParams::tripodExitPosition, 'txps', "TripodExitPosition", "Tripod Release Distance", "Metres of movement away from the locked pose that releases the tripod", 0.01f);		desc.AddMember(&SPhoneTripodParams::tripodBlendTime, 'tbld', "TripodBlendTime", "Tripod Release Blend", "Seconds spent blending from the locked pose back to the live pose", 0.15f);	}	bool tripodEnabled = true;	Schematyc::Range<0, 1, 0, 1> tripodEnterSpeed = 0.015f;	Schematyc::Range<0, 2, 0, 1> tripodHoldTime = 0.25f;	Schematyc::Range<0, 1, 0, 1> tripodExitPosition = 0.01f;	Schematyc::Range<0, 2, 0, 1> tripodBlendTime = 0.15f;};struct SPhoneLensLinkParams{	inline bool operator==(const SPhoneLensLinkParams& rhs) const { return 0 == memcmp(this, &rhs, sizeof(rhs)); }	static void ReflectType(Schematyc::CTypeDesc<SPhoneLensLinkParams>& desc)	{		desc.SetGUID("{D73AFC60-F91E-48D3-86FB-AEC7008D793D}"_cry_guid);		desc.SetLabel("Cinematic Lens Link");		desc.AddMember(&SPhoneLensLinkParams::driveLens, 'lens', "DriveLens", "Drive Cinematic Camera", "Forward the focal length / aperture / focus distance / EV sent by the phone to a Cinematic Camera component on this entity", true);		desc.AddMember(&SPhoneLensLinkParams::lensArmsEffects, 'larm', "LensArmsEffects", "Lens Arms DOF And Exposure", "Let the phone switch depth of field and exposure control on when it starts sending lens values", true);	}	bool driveLens = true;	bool lensArmsEffects = true;};struct SPhoneDebugParams{	inline bool operator==(const SPhoneDebugParams& rhs) const { return 0 == memcmp(this, &rhs, sizeof(rhs)); }	static void ReflectType(Schematyc::CTypeDesc<SPhoneDebugParams>& desc)	{		desc.SetGUID("{E84BFD71-FA2F-49E4-87FC-BFD8119E8A4E}"_cry_guid);		desc.SetLabel("Legacy And Debug");		desc.AddMember(&SPhoneDebugParams::smoothingHalfLife, 'smoo', "Smoothing", "Smoothing Half Life", "Superseded by the Pose Filter; leave at 0. When above 0 it adds one more exponential smoothing pass after the filter pipeline", 0.0f);		desc.AddMember(&SPhoneDebugParams::signalTimeout, 'tout', "Timeout", "Signal Timeout", "Seconds without a valid pose before tracking is considered lost", 2.0f);		desc.AddMember(&SPhoneDebugParams::debugDraw, 'dbg', "DebugDraw", "Debug Draw", "Draw connection and pose statistics on screen", false);	}	Schematyc::Range<0, 5, 0, 1> smoothingHalfLife = 0.0f;	Schematyc::Range<0, 60, 0, 10> signalTimeout = 2.0f;	bool debugDraw = false;};class CPhoneTrackerComponent final : public IEntityComponent{public:	CPhoneTrackerComponent() = default;	virtual ~CPhoneTrackerComponent();	static void ReflectType(Schematyc::CTypeDesc<CPhoneTrackerComponent>& desc)	{		desc.SetGUID("{6D5B1F52-4C2E-47D6-9C2B-2F0C3E77A101}"_cry_guid);		desc.SetEditorCategory("Tracking");		desc.SetLabel("Phone Tracker");		desc.SetDescription("Receives 6DoF poses from the Android phone tracker over UDP and applies them to this entity");		desc.SetComponentFlags({ IEntityComponent::EFlags::Singleton });		desc.AddMember(&CPhoneTrackerComponent::m_connection, 'gcon', "Connection", "Connection", "", SPhoneConnectionParams());		desc.AddMember(&CPhoneTrackerComponent::m_mapping, 'gmap', "TransformMapping", "Transform Mapping", "", SPhoneMappingParams());		desc.AddMember(&CPhoneTrackerComponent::m_filter, 'gflt', "PoseFilter", "Pose Filter", "", SPhoneFilterParams());		desc.AddMember(&CPhoneTrackerComponent::m_tripod, 'gtrp', "VirtualTripod", "Virtual Tripod", "", SPhoneTripodParams());		desc.AddMember(&CPhoneTrackerComponent::m_lensLink, 'glnk', "CinematicLensLink", "Cinematic Lens Link", "", SPhoneLensLinkParams());		desc.AddMember(&CPhoneTrackerComponent::m_debug, 'gdbg', "LegacyAndDebug", "Legacy And Debug", "", SPhoneDebugParams());	}	static void Register(Schematyc::CEnvRegistrationScope& componentScope);	// IEntityComponent	virtual void Initialize() override;	virtual void OnShutDown() override;	virtual Cry::Entity::EventFlags GetEventMask() const override;	virtual void ProcessEvent(const SEntityEvent& event) override;	// ~IEntityComponent	//! Re-samples the tracker origin from the next pose and asks the phone to reset its own origin.	void Recenter();	void SetTrackingEnabled(bool enable);	bool IsTracking() const { return m_isTracking; }	//! Number this tracker answers to in logs and the overlay: the Tracker ID property, or its	//! creation order (1-based) when the property is left at 0.	int GetTrackerId() const;protected:	//! Position of this component in the creation-order registry (0-based), -1 if absent.	int RegistryIndex() const;	//! Another tracker in the level already listening on our port, or nullptr.	const CPhoneTrackerComponent* FindPortHolder() const;	//! The entity the tracker actually drives: the active cinematic camera when Follow Active	//! Camera is on and one exists, otherwise this component's own entity. Never nullptr.	IEntity* GetTargetEntity();	//! Once per frame: notices a camera switch and re-anchors on the new target.	void UpdateTarget();	void OpenSocket();	void ApplyLensPacket(const SLensPacket& packet);	void RunAutofocus(ICinematicCameraOptics* pOptics);	ICinematicCameraOptics* GetOptics();	void CloseSocket();	void ReceivePackets();	void ApplyPose(float frameTime);	QuatT MapToWorld(const Vec3& trackerPosition, const Quat& trackerRotation) const;	void SyncFilterParams();	void SendControl(EControlCommand cmd, int32 param = 0);	void DrawDebug() const;	// Reflected properties	// Reflected property groups	SPhoneConnectionParams m_connection;	SPhoneMappingParams m_mapping;	SPhoneFilterParams m_filter;	SPhoneTripodParams m_tripod;	SPhoneLensLinkParams m_lensLink;	SPhoneDebugParams m_debug;	// Runtime state	CRYSOCKET      m_socket = CRY_INVALID_SOCKET;	bool           m_wsaStarted = false;	CRYSOCKADDR_IN m_peer;	bool           m_hasPeer = false;	uint32         m_controlSeq = 0;	//! Why the socket is closed although the tracker is enabled - shown in the overlay.	//! Empty while listening or while deliberately disabled.	string         m_socketProblem;	//! Every live tracker component, in creation order. Main thread only.	static std::vector<CPhoneTrackerComponent*> s_registry;	QuatT  m_referenceTransform = QuatT(IDENTITY);  //!< Entity transform captured when tracking started.	QuatT  m_trackerOrigin = QuatT(IDENTITY);       //!< Tracker pose treated as the zero point.	bool   m_hasOrigin = false;	uint32 m_originEpoch = 0;	bool   m_recenterRequested = false;	CPoseFilter m_poseFilter;                       //!< Runs in tracker space, before the world mapping.	bool   m_signalWasLost = false;                 //!< Set when Signal Timeout expires, so we can reset the filter on recovery.	QuatT  m_targetTransform = QuatT(IDENTITY);     //!< Latest pose mapped into world space.	QuatT  m_currentTransform = QuatT(IDENTITY);    //!< Smoothed transform actually written to the entity.	bool   m_hasTarget = false;	bool   m_isTracking = false;	float  m_timeSinceValidPose = 0.0f;	uint32 m_lastSeq = 0;	uint32 m_packetsReceived = 0;	uint32 m_packetsLost = 0;	uint8  m_batteryPct = 0;	uint8  m_appFps = 0;	uint8  m_trackingState = 0;	// Camera-follow state.	TGetActiveCinematicCameraEntityFn m_pfnActiveCameraEntity = nullptr;	bool     m_activeCameraLookedUp = false;	EntityId m_targetEntityId = INVALID_ENTITYID;   //!< Entity currently driven; switches re-anchor.	// Lens state mirrored from the phone (only meaningful while m_lensLink.driveLens is set).	ICinematicCameraOptics* m_pOptics = nullptr;	bool   m_opticsLookedUp = false;	bool   m_hasLensState = false;	float  m_focalLengthMm = 0.0f;	float  m_apertureFNumber = 0.0f;	float  m_focusDistanceM = 0.0f;	float  m_evCompensation = 0.0f;	uint32 m_lensIso = 0;};} // namespace PhoneTracker} // namespace Cry